def update_last_applied_manifest_list_from_resp(
    last_applied_manifest, observer_schema, response
):
    for i, schema_item in enumerate(observer_schema):
        if i < len(response):
            if isinstance(schema_item, dict) and isinstance(response[i], dict):
                if i < len(last_applied_manifest):
                    update_last_applied_manifest_dict_from_resp(
                        last_applied_manifest[i], schema_item, response[i]
                    )
                else:
                    last_applied_manifest.append(schema_item.copy())
            elif isinstance(schema_item, list) and isinstance(response[i], list):
                if i < len(last_applied_manifest):
                    update_last_applied_manifest_list_from_resp(
                        last_applied_manifest[i], schema_item, response[i]
                    )
                else:
                    last_applied_manifest.append(schema_item.copy())
            elif i >= len(last_applied_manifest):
                last_applied_manifest.append(response[i])

