def _extract_number_and_supplment_from_issue_element(issue):
    issue = issue.lower().strip()
    number = None
    suppl = None

    # Check for number
    if issue.isdigit():
        number = issue
    else:
        import re
        match = re.match(r'(\d+)(?:-?\d+)?\s*(spe|suppl?\.?\s?pr?|s|sp|supplement?)?\s*(\d+)?', issue)
        if match:
            number = match.group(1)
            suppl_text = match.group(2)
            suppl_number = match.group(3)

            if suppl_text:
                suppl = 'suppl'
                if suppl_number:
                    suppl += f' {suppl_number}'

    return number, suppl

