def absorb(self, args):
    result = []
    for expr in args:
        if isinstance(expr, tuple) and len(expr) == 3:
            op, left, right = expr
            if op == '&':
                if right == (('|', left, '_')):  # A & (A | B) = A
                    result.append(left)
                elif right == (('|', ('~', left), '_')):  # A & (~A | B) = A & B
                    result.append(('&', left, right[2]))
            elif op == '|':
                if right == (('&', left, '_')):  # A | (A & B) = A
                    result.append(left)
                elif right == (('&', ('~', left), '_')):  # A | (~A & B) = A | B
                    result.append(('|', left, right[2]))
            else:
                result.append(expr)
        else:
            result.append(expr)
    return result

