    config_dict = {}
    log_records = []

    for filename in config_filenames:
        try:
            with open(filename, 'r') as file:
                config = file.read()
                # Here you would typically parse the config, e.g., using json, yaml, etc.
                # For demonstration, let's assume it's a simple key=value format
                parsed_config = {}
                for line in config.splitlines():
